// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/files.ts`. Edit the source and run `just generate`.
// The reads of the files of one change: the change file, the package files, and the text of the whole change.
// A file that fails its format check still gives a record, with its `errors`, so a command can count the errors.

import path from "node:path";
import { ARCHIVE_DIR, SPEC_ROOT, SPECS_DIR } from "../../../kernel/paths.ts";
import { sectionErrors } from "../domain/brief.ts";
import { checkFront, type Front, parseFront } from "../domain/front.ts";
import { markersOf, requirementsOf } from "../domain/requirements.ts";
import type { SpecStore } from "./store.ts";

/** One package file of a change. */
export interface PackageFile {
  readonly id: string;
  /** The path of the file, relative to the root of the store. */
  readonly path: string;
  readonly title: string;
  readonly wave: number;
  readonly deps: readonly string[];
  readonly owns: readonly string[];
  readonly satisfies: readonly string[];
  readonly verify: string;
  readonly status: string;
  readonly text: string;
  /** The format errors of the front matter and of the sections, each as `path:line: message`. */
  readonly errors: readonly string[];
}

/** The `change.md` file of a change. */
export interface ChangeFile {
  readonly id: string;
  readonly path: string;
  readonly size: string;
  readonly status: string;
  readonly verify: string;
  readonly text: string;
  readonly errors: readonly string[];
}

const text = (front: Front, key: string): string => {
  const value = front[key];
  return typeof value === "string" ? value : "";
};

const list = (front: Front, key: string): string[] => {
  const value = front[key];
  return Array.isArray(value) ? value : [];
};

/** The path of the folder of the change `id`. */
export const changeDir = (id: string): string => path.posix.join(SPEC_ROOT, id);

/** The format errors of the front matter of `file`, as `path:line: message`. */
const frontErrors = (
  file: string,
  body: string,
  kind: "change" | "package",
): string[] => {
  const checked = checkFront(body, kind);
  return checked.ok
    ? []
    : checked.errors.map((e) => `${file}:${e.line}: ${e.message}`);
};

/** The package files of the change `id`, sorted by wave and then by id. A change with no `packages/` folder gives an empty list. */
export const readPackages = async (
  store: SpecStore,
  id: string,
): Promise<PackageFile[]> => {
  const dir = path.posix.join(changeDir(id), "packages");
  const found: PackageFile[] = [];
  for (const name of await store.markdown(dir)) {
    const file = path.posix.join(dir, name);
    const body = (await store.files.read(file)) ?? "";
    const front = parseFront(body);
    const values = front.ok ? front.value.front : {};
    found.push({
      id: text(values, "id") || name.replace(/\.md$/, ""),
      path: file,
      title: text(values, "title"),
      wave: Number.parseInt(text(values, "wave"), 10) || 0,
      deps: list(values, "deps"),
      owns: list(values, "owns"),
      satisfies: list(values, "satisfies"),
      verify: text(values, "verify"),
      status: text(values, "status") || "planned",
      text: body,
      errors: [
        ...frontErrors(file, body, "package"),
        ...sectionErrors(body).map((e) => `${file}:${e.line}: ${e.message}`),
      ],
    });
  }
  return found.sort(
    (a, b) =>
      a.wave - b.wave || a.id.localeCompare(b.id, "en", { numeric: true }),
  );
};

/** `change.md` of the change `id`, or null when the file is missing. */
export const readChange = async (
  store: SpecStore,
  id: string,
): Promise<ChangeFile | null> => {
  const file = path.posix.join(changeDir(id), "change.md");
  const body = await store.files.read(file);
  if (body === null) return null;
  const front = parseFront(body);
  const values = front.ok ? front.value.front : {};
  return {
    id,
    path: file,
    size: text(values, "size"),
    status: text(values, "status") || "draft",
    verify: text(values, "verify"),
    text: body,
    errors: frontErrors(file, body, "change"),
  };
};

/** One Markdown file of a change, with its path and text. */
export interface Source {
  readonly path: string;
  readonly text: string;
}

/** `change.md`, the requirements files, `design.md`, and the package files of the change `id`, for the reads that scan the whole change. */
export const changeSources = async (
  store: SpecStore,
  id: string,
): Promise<Source[]> => {
  const dir = changeDir(id);
  const names = [
    "change.md",
    "design.md",
    ...(await store.markdown(path.posix.join(dir, "requirements"))).map((n) =>
      path.posix.join("requirements", n),
    ),
    ...(await store.markdown(path.posix.join(dir, "packages"))).map((n) =>
      path.posix.join("packages", n),
    ),
  ];
  const sources: Source[] = [];
  for (const name of names) {
    const file = path.posix.join(dir, name);
    const body = await store.files.read(file);
    if (body !== null) sources.push({ path: file, text: body });
  }
  return sources;
};

/** The files that hold the requirements of the change `id`: `requirements/*.md`, or `change.md` of a trivial change. */
export const requirementSources = (sources: readonly Source[]): Source[] =>
  sources.filter(
    (s) => s.path.includes("/requirements/") || s.path.endsWith("/change.md"),
  );

/** The numbers of the requirement IDs in `specs/`, in each open change, and in the archive. A new ID must be greater than all of them. */
export const usedRequirementNumbers = async (
  store: SpecStore,
): Promise<number[]> => {
  const numbers: number[] = [];
  const add = (body: string | null): void => {
    for (const r of requirementsOf(body ?? "").requirements) numbers.push(r.id);
  };
  for (const name of await store.markdown(SPECS_DIR))
    add(await store.files.read(path.posix.join(SPECS_DIR, name)));
  const folders = [
    ...(await store.changes()).map(changeDir),
    ...(await store.files.list(ARCHIVE_DIR)).map((n) =>
      path.posix.join(ARCHIVE_DIR, n),
    ),
  ];
  for (const dir of folders) {
    add(await store.files.read(path.posix.join(dir, "change.md")));
    const req = path.posix.join(dir, "requirements");
    for (const name of await store.markdown(req))
      add(await store.files.read(path.posix.join(req, name)));
  }
  return numbers;
};

/** The number of open `[NEEDS CLARIFICATION]` markers in the files of the change `id`. */
export const openMarkers = async (
  store: SpecStore,
  id: string,
): Promise<number> =>
  (await changeSources(store, id)).reduce(
    (sum, s) => sum + markersOf(s.text).length,
    0,
  );
